#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> egcd_variant(long long a, long long b) {
    long long rA = a, rB = b;
    long long sA = 1, sB = 0;
    long long tA = 0, tB = 1;
    while (rB != 0) {
        long long q = rA / rB;
        long long temp;
        temp = rA; rA = rB; rB = temp - q * rB;
        temp = sA; sA = sB; sB = temp - q * sB;
        temp = tA; tA = tB; tB = temp - q * tB;
    }
    return {rA, sA};
}

vector<long long> compute_coeffs(int n, long long M) {
    vector<long long> C(n + 1, 0);
    C[n] = 1;
    for (int k = n - 1; k >= 0; --k) {
        C[k] = (C[k + 1] * (k + 1)) % M;
        if (C[k] == 0) {
            break;
        }
    }
    return C;
}

long long calculate(int n, long long M) {
    vector<vector<vector<long long>>> K;
    K.push_back({{1}});
    for (int i = 0; i < n - 1; ++i) {
        auto &prev_layer = K[i];
        int size_prev = (int)prev_layer.size();
        vector<vector<long long>> new_layer(size_prev + i + 1, vector<long long>(i + 2, 0));
        K.push_back(new_layer);
        for (int j = 0; j < size_prev; ++j) {
            for (int k = 0; k < (int)prev_layer[j].size(); ++k) {
                long long val = prev_layer[j][k];
                for (int h = 0; h <= i; ++h) {
                    K[i + 1][j + h][k] = (K[i + 1][j + h][k] + val) % M;
                }
                K[i + 1][j + i + 1][i + 1] = (K[i + 1][j + i + 1][i + 1] + val) % M;
            }
        }
    }
    vector<long long> C = compute_coeffs(n, M);
    long long total = 0;
    for (int i = 1; i < n; ++i) {
        auto &layer = K[i];
        int ni = (int)layer.size();
        int mi = (int)layer[0].size();
        vector<vector<long long>> S(ni, vector<long long>(mi, 0));
        for (int j = 0; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = layer[j][k];
            }
        }
        for (int j = 0; j < ni; ++j) {
            for (int k = mi - 2; k >= 0; --k) {
                S[j][k] = (S[j][k] + S[j][k + 1]) % M;
            }
        }
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = (S[j][k] + S[j - 1][k]) % M;
            }
        }
        long long sum_i = 0;
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi - 1; ++k) {
                sum_i += (layer[j][k] * S[j - 1][k + 1]) % M;
                sum_i %= M;
            }
        }
        long long c = C[i + 1];
        sum_i = (sum_i * c) % M;
        total = (total + sum_i) % M;
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    cin >> n >> m;
    cout << calculate(n, m) << "\n";
    return 0;
}

